const {chromium,webkit}=require('playwright'),fs=require('fs');(async()=>{fs.mkdirSync('qa/v442/reviewed-planning',{recursive:true});for(const [name,type]of Object.entries({chromium,webkit}))for(const width of[320,393,1280]){const b=await type.launch({headless:true}),p=await b.newPage({viewport:{width,height:900}});await p.goto('http://127.0.0.1:8788/backend/tools/strategic_budget_v442/review/preview.html');await p.getByRole('heading',{name:'Orçado × realizado'}).waitFor();const text=await p.locator('body').innerText();if(!text.includes('Total orçado: Não definido')||!text.includes('500,00')||!text.includes('nenhum corte ou meta zero'))throw Error('Planning semantics failed');if(await p.evaluate(()=>document.documentElement.scrollWidth>innerWidth))throw Error('Document overflow');await p.screenshot({path:'qa/v442/reviewed-planning/'+name+'-'+width+'.png',fullPage:true});await b.close();}console.log('PASS synthetic reviewed planning preview Chromium/WebKit; not owner app validation');})().catch(e=>{console.error(e);process.exit(1)});